SELECT COUNT(*) AS bag_count
FROM public_academic_bag ab
WHERE ab.is_active = TRUE;

SELECT COUNT(*) AS order_count
FROM public_logistics_orders lo
WHERE lo.is_active = TRUE;

SELECT lo.*
FROM public_logistics_orders lo
WHERE date_trunc('month', lo.created_at) = date_trunc('month', CURRENT_DATE);

SELECT ls.*
FROM public_logistics_shipments ls
WHERE ls.tracking_id IS NULL OR ls.tracking_id = '';

SELECT ROUND(SUM(COALESCE(ab.gross_price::numeric, 0)), 2) AS total_gross_revenue
FROM public_academic_bag ab
WHERE ab.payment_status::integer = 3;

SELECT ROUND(SUM(COALESCE(ab.net_price::numeric, 0)), 2) AS total_net_revenue
FROM public_academic_bag ab
WHERE ab.payment_status::integer = 3;
